import { httpRouter } from "convex/server";
import { httpAction } from "./_generated/server";
import { internal } from "./_generated/api";
import { authComponent, createAuth } from "./auth";
import { reportError } from "./lib/errors";
import { tokenIdentifierFromIssuerAndSubject } from "./lib/authIdentity";

/* ── Shared-Lix auth helpers ───────────────────────────────────────
 * The /lsp/* routes are hit by the Lix SDK's sync process, which uses raw
 * fetch. We can't rely on Convex's automatic ctx.auth identity here; instead
 * we verify the better-auth session cookie (or the cross-domain
 * Better-Auth-Cookie header) and only let accepted collaborators read or
 * write a shared document. */

/** Verify the caller's Better Auth session and return its Convex identity key. */
async function getAuthenticatedTokenIdentifier(
  ctx: any,
  request: Request,
): Promise<string | null> {
  try {
    const auth = createAuth(ctx);
    // The cross-domain client sends the session via the Better-Auth-Cookie
    // header; better-auth's session middleware reads the Cookie header. Fold
    // the former into the latter so verification works regardless of whether
    // the request flows through the registered auth handler.
    const headers = new Headers(request.headers);
    const crossDomainCookie = headers.get("better-auth-cookie");
    if (crossDomainCookie && !headers.get("cookie")) {
      headers.set("cookie", crossDomainCookie);
    }
    const session = await (auth as any).api.getSession({
      headers,
      query: { disableCookieCache: true },
    });
    return tokenIdentifierFromIssuerAndSubject(
      process.env.CONVEX_SITE_URL,
      session?.user?.id,
    );
  } catch {
    return null;
  }
}

/** Extract the lix_id from the JSON body of get/pull/push requests. */
function getLixIdFromBody(path: string, body: ArrayBuffer): string | null {
  if (path === "/lsp/new-v1") return null;
  if (body.byteLength === 0) return null;
  try {
    const json = JSON.parse(new TextDecoder().decode(body));
    return typeof json?.lix_id === "string" ? json.lix_id : null;
  } catch {
    return null;
  }
}

const http = httpRouter();

authComponent.registerRoutes(http, createAuth, { cors: true });

/* ── CLI / MCP integration API ─────────────────────────────────────
 * The local tools use a personal bearer token created from Settings. The
 * database stores only its SHA-256 digest; after resolving that digest here,
 * every operation runs through an internal function with the verified owner.
 */

const INTEGRATION_INCLUDES = new Set([
  "content",
  "brief",
  "feedback",
  "rubric",
  "suggestions",
  "citations",
]);
const DEFAULT_INTEGRATION_INCLUDES = [...INTEGRATION_INCLUDES];
const MAX_INTEGRATION_BODY_BYTES = 2 * 1024 * 1024;

function integrationJson(data: unknown, status = 200): Response {
  return Response.json(data, {
    status,
    headers: { "cache-control": "no-store" },
  });
}

function integrationError(message: string, status: number): Response {
  return integrationJson({ ok: false, error: message }, status);
}

function integrationPublicError(error: unknown): string {
  const message =
    (error instanceof Error ? error.message : "")
      .split("\n", 1)[0]
      ?.replace(/^.*Uncaught Error:\s*/, "")
      .trim() ?? "";
  const safeFragments = [
    "is required",
    "must be",
    "characters or fewer",
    "changed since it was read",
    "can hold at most",
    "At most 100 citations",
    "Each citation",
  ];
  return safeFragments.some((fragment) => message.includes(fragment))
    ? message
    : "Integration request failed";
}

function integrationRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function integrationString(value: unknown, field: string): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`${field} is required`);
  }
  return value.trim();
}


/* ── Lix server protocol relay ──────────────────────────────────────
 * The LSP routes. Each is a thin httpAction that authenticates the caller's
 * better-auth session, extracts the lix_id from the request body, and
 * forwards the raw body to `lixRelay.handleLspRequest` (a `"use node"` action
 * that runs the Lix SDK). The action re-checks the caller's collaborator role
 * on the document before letting the Lix SDK read or mutate the blob, then
 * persists the updated blob and returns the serialized response.
 *
 * `new-v1` is not exposed here — shared documents are created through the
 * authenticated `shareFolio` action so collaboration metadata is always set
 * up alongside the blob. */

const LSP_ROUTES = [
  "/lsp/new-v1",
  "/lsp/get-v1",
  "/lsp/push-v1",
  "/lsp/pull-v1",
];

for (const path of LSP_ROUTES) {
  http.route({
    path,
    method: "POST",
    handler: httpAction(async (ctx, request) => {
      // Shared documents are never created via the LSP new-v1 route; sharing
      // is done through the authenticated shareFolio action. Block this path
      // so we don't create orphaned blobs without collaboration metadata.
      if (path === "/lsp/new-v1") {
        return new Response("not found", { status: 404 });
      }

      const body = await request.arrayBuffer().catch(() => new ArrayBuffer(0));
      const lixId = getLixIdFromBody(path, body);
      if (!lixId) {
        return new Response("missing lix_id", { status: 400 });
      }

      const userId = await getAuthenticatedTokenIdentifier(ctx, request);
      if (!userId) {
        return new Response("unauthorized", { status: 401 });
      }

      try {
        const result = await ctx.runAction(internal.lixRelay.handleLspRequest, {
          path,
          method: "POST",
          body,
          lixId,
          userId,
        });
        return new Response(result.body ? new Blob([result.body]) : null, {
          status: result.status,
          headers: result.headers,
        });
      } catch (err) {
        // A relay failure drops a multiplayer change-set silently; report
        // so we have a signal before a collaborator notices data loss.
        reportError({
          feature: "lixRelay.lsp",
          error: err,
          context: { path, lixId },
        });
        return new Response("relay error", { status: 502 });
      }
    }),
  });
}

export default http;
/**
 * Intercepts Lix sync fetch calls so they carry the better-auth session.
 *
 * The Lix SDK's `initSyncProcess` issues raw `fetch()` requests to the
 * `/lsp/*` relay on the Convex site URL. On a cross-domain deployment the
 * browser won't automatically send the better-auth session cookie, so the
 * cross-domain client stores it in localStorage and exposes `getCookie()`.
 * We intercept same-origin-to-the-relay LSP requests and add the
 * `Better-Auth-Cookie` header, which the server converts back into a `Cookie`
 * header for session verification.
 */
import { authClient } from "./auth-client";

const CONVEX_SITE_URL = (
  import.meta.env.VITE_CONVEX_SITE_URL as string | undefined
)?.replace(/\/$/, "");

function isLspRequest(input: RequestInfo | URL): boolean {
  if (!CONVEX_SITE_URL) return false;
  const url =
    typeof input === "string"
      ? input
      : input instanceof Request
        ? input.url
        : input.toString();
  return url.startsWith(`${CONVEX_SITE_URL}/lsp/`);
}

function getStoredAuthCookie(): string | undefined {
  try {
    return ((authClient as any).getCookie?.() as string | undefined) ?? "";
  } catch {
    return "";
  }
}

let installed = false;

/** Install a fetch wrapper that adds the auth cookie to Lix LSP requests. */
export function installLixAuthInterceptor(): void {
  if (typeof window === "undefined" || installed) return;
  installed = true;

  const originalFetch = window.fetch;
  const wrapper = async function (
    this: unknown,
    input: RequestInfo | URL,
    init?: RequestInit,
  ): Promise<Response> {
    if (isLspRequest(input)) {
      const cookie = getStoredAuthCookie();
      if (cookie) {
        const headers = new Headers(init?.headers);
        headers.set("Better-Auth-Cookie", cookie);
        init = { ...init, headers };
      }
    }
    return originalFetch.call(this, input, init);
  };
  window.fetch = wrapper as typeof window.fetch;
}

"use node";

/**
 * Lix server protocol relay — the bridge between browsers running Lix sync
 * and the shared Lix blobs stored in Convex file storage.
 *
 * When a Pro user shares a folio, its Lix blob is promoted to a server-hosted
 * instance (see convex/collaboration.ts `shareFolio`). The owner and invited
 * collaborators then open it with `lix_sync: true` and `initSyncProcess`
 * polls these endpoints every ~1-2 s, pushing local changes and pulling
 * remote ones. Lix's vector-clock + `mergeTheirState` engine handles the
 * merge.
 *
 * Each request lifecycle:
 *   1. Read the `storageId` from the `sharedLixBlobs` table (internal query).
 *   2. Download the blob via `ctx.storage.get(storageId)` (action-only API).
 *   3. `openLixInMemory` → run the server-protocol route → persist the
 *      modified blob via `ctx.storage.store()` → save the new `storageId`
 *      via an internal mutation (and delete the old file).
 *
 * Blobs live in Convex file storage (not `v.bytes()` in a table row) so they
 * are not subject to the typical row-size limits — a long document's Lix
 * state can be tens of KB to several hundred KB.
 */
import { internalAction } from "./_generated/server";
import { v } from "convex/values";
import { internal } from "./_generated/api";
import {
  openLixInMemory,
  toBlob,
  createServerProtocolHandler,
  type Lix,
} from "@lix-js/sdk";

/* ── The action: runs createServerProtocolHandler with ctx.storage ── */

export const handleLspRequest = internalAction({
  args: {
    path: v.string(),
    method: v.string(),
    body: v.optional(v.bytes()),
    lixId: v.string(),
    userId: v.string(),
  },
  handler: async (ctx, args) => {
    // Authorization: check the caller's role on the shared document before
    // letting the Lix SDK touch the blob.
    const role = await ctx.runQuery(
      internal.collaboration.getCollaboratorRole,
      {
        lixId: args.lixId,
        userId: args.userId,
      },
    );
    if (!role) {
      return {
        status: 403,
        headers: { "Content-Type": "application/json" },
        body: new TextEncoder().encode(JSON.stringify({ error: "Forbidden" })),
      };
    }
    // Commenters may download (get/pull) but may not push changes.
    const canWrite = role === "owner" || role === "editor";
    if (
      (args.path === "/lsp/push-v1" || args.path === "/lsp/new-v1") &&
      !canWrite
    ) {
      return {
        status: 403,
        headers: { "Content-Type": "application/json" },
        body: new TextEncoder().encode(JSON.stringify({ error: "Forbidden" })),
      };
    }

    // Serialize pushes per lixId so two concurrent push-v1 requests don't
    // both read the same base blob and clobber each other on write.
    const needsLock = args.path === "/lsp/push-v1";
    if (needsLock) {
      const acquired = await ctx.runMutation(internal.sharedLix.acquireLock, {
        lixId: args.lixId,
      });
      if (!acquired) {
        return {
          status: 409,
          headers: { "Content-Type": "application/json" },
          body: new TextEncoder().encode(
            JSON.stringify({ error: "Conflict: another push is in progress" }),
          ),
        };
      }
    }

    try {
      // Build a minimal LspEnvironment backed by Convex file storage.
      // The environment is request-scoped: openLix caches the in-memory state
      // for the duration of the handler, then closeLix persists it.
      const openInstances = new Map<
        string,
        { lix: Lix; id: string; storageId: string }
      >();

      const environment = {
        get: async () => undefined,
        set: async () => {},
        has: async () => false,
        delete: async () => {},

        hasLix: async ({ id }: { id: string }) => {
          return await ctx.runQuery(internal.sharedLix.has, { lixId: id });
        },

        getLix: async ({ id }: { id: string }) => {
          const row = await ctx.runQuery(internal.sharedLix.get, {
            lixId: id,
          });
          if (!row?.storageId) return undefined;
          const blob = await ctx.storage.get(row.storageId);
          return blob ?? undefined;
        },

        setLix: async ({
          id,
          blob,
          ownerId,
          folioId,
          folioName,
        }: {
          id: string;
          blob: Blob;
          ownerId?: string;
          folioId?: string;
          folioName?: string;
        }) => {
          const storageId = await ctx.storage.store(blob);
          if (ownerId && folioId && folioName) {
            await ctx.runMutation(internal.sharedLix.set, {
              lixId: id,
              ownerId,
              folioId,
              folioName,
              storageId,
            });
          } else {
            // Update existing row's storageId; delete the old file.
            const oldStorageId = await ctx.runMutation(
              internal.sharedLix.updateStorageId,
              { lixId: id, storageId },
            );
            if (oldStorageId && oldStorageId !== storageId) {
              try {
                await ctx.storage.delete(oldStorageId);
              } catch {
                // Best-effort cleanup; the old file will be orphaned but
                // that's not a correctness issue.
              }
            }
          }
        },

        openLix: async ({ id }: { id: string }) => {
          const blob = await environment.getLix({ id });
          if (!blob) throw new Error(`Lix ${id} not found`);
          const lix = await openLixInMemory({
            blob,
            keyValues: [
              { key: "lix_sync" as any, value: "false" as any } as any,
            ],
          });
          const row = await ctx.runQuery(internal.sharedLix.get, {
            lixId: id,
          });
          const storageId = row?.storageId ?? "";
          const connectionId = `${id}-${Date.now()}-${Math.random()}`;
          openInstances.set(connectionId, { lix, id, storageId });
          return { lix, id, connectionId };
        },

        closeLix: async ({
          id,
          connectionId,
        }: {
          id: string;
          connectionId: string;
        }) => {
          const entry = openInstances.get(connectionId);
          if (entry) {
            const blob = await toBlob({ lix: entry.lix });
            const newStorageId = await ctx.storage.store(blob);
            const oldStorageId = await ctx.runMutation(
              internal.sharedLix.updateStorageId,
              { lixId: id, storageId: newStorageId },
            );
            if (oldStorageId && oldStorageId !== newStorageId) {
              try {
                await ctx.storage.delete(oldStorageId);
              } catch {}
            }
          }
          openInstances.delete(connectionId);
        },
 * Internal mutation that creates both the sharedLixBlobs metadata row and
 * the owner collaborator row. Called by the `shareFolio` action after the
 * blob has been stored via `ctx.storage.store()`.
 */
export const createShareRecord = internalMutation({
  args: {
    lixId: v.string(),
    ownerId: v.string(),
    folioId: v.string(),
    folioName: v.string(),
    storageId: v.id("_storage"),
  },
  handler: async (ctx, args) => {
    await ctx.runMutation(internal.sharedLix.set, args);
    const now = Date.now();
    await ctx.db.insert("collaborators", {
      lixId: args.lixId,
      userId: args.ownerId,
      role: "owner",
      status: "accepted",
      invitedAt: now,
      acceptedAt: now,
    });
  },
});

export const shareFolio = action({
  args: {
    folioId: v.string(),
    folioName: v.string(),
    lixId: v.string(),
    blob: v.bytes(),
  },
  handler: async (
    ctx,
    args,
  ): Promise<{ lixId: string; alreadyShared: boolean }> => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const userId = identity.tokenIdentifier;

    // Pro gate — only subscribers can promote a local doc to shared.
    const isPro = await userIsPro(
      ctx,
      identity.subject || identity.tokenIdentifier,
    );
    if (!isPro) {
      throw new Error("Sharing documents is a Pro feature.");
    }

    // Don't create a duplicate if this folio is already shared.
    const existing = await ctx.runQuery(internal.sharedLix.get, {
      lixId: args.lixId,
    });
    if (existing) {
      return { lixId: existing.lixId, alreadyShared: true };
    }

    // Store the blob in Convex file storage (action-only API), then create
    // the metadata + owner collaborator row via an internal mutation.
    const storageId = await ctx.storage.store(new Blob([args.blob]));
    await ctx.runMutation(internal.collaboration.createShareRecord, {
      lixId: args.lixId,
      ownerId: userId,
      folioId: args.folioId,
      folioName: args.folioName,
      storageId,
    });

    return { lixId: args.lixId, alreadyShared: false };
  },
});

